/* Every make/model pair, flattened once for searching. */
const VPIC_FLAT = Object.entries(VPIC_MODELS).flatMap(([mk, models]) =>
  Object.entries(models).map(([md, yrs]) => ({ mk, md, y0: yrs[0], y1: yrs[1] })));

/* Models this make is known to have built, for the add-vehicle datalist. */
function vpicModelsFor(make) {
  return Object.keys(VPIC_MODELS[make] || {});
}
